// n8n Code node (JavaScript)
// Objetivo: devolver un array con strings tipo: "Nombre & Sabor (si aplica) & Contenido Neto"
// Soporta:
// - items normales (cada item es un producto)
// - un solo item cuyo json ES un array de productos (como en tu ejemplo)
// - salidas tipo Airtable con `fields`
// - keys con espacios: "Contenido Neto", etc.

const SOURCE_NODE = 'Search records';

// 1) Traemos items del nodo "Search records" si existe; si no, usamos el input directo
let items = [];
try {
  items = $items(SOURCE_NODE);
} catch (e) {
  items = $input.all();
}

// 2) Normalizamos a "records" (array de objetos producto)
const records = [];

for (const item of items) {
  const j = item?.json;

  if (Array.isArray(j)) {
    // Caso: un item cuyo json ya es un array de productos
    records.push(...j);
    continue;
  }

  if (Array.isArray(j?.records)) {
    // Caso: { records: [...] }
    records.push(...j.records);
    continue;
  }

  // Caso típico: un producto por item
  if (j?.fields && typeof j.fields === 'object') {
    // Airtable style: { id, fields: {...} }
    records.push({ id: j.id, createdTime: j.createdTime, ...j.fields });
  } else if (j && typeof j === 'object') {
    records.push(j);
  }
}

// 3) Helpers seguros
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());

const getField = (rec, keys) => {
  for (const k of keys) {
    if (rec && Object.prototype.hasOwnProperty.call(rec, k)) {
      const val = clean(rec[k]);
      if (val) return val;
    }
  }
  return '';
};

// 4) Formateamos "Nombre & Sabor (si aplica) & Contenido"
const product_options = [];

for (const rec of records) {
  const nombre = getField(rec, ['Nombre', 'name', 'producto', 'Product', 'Title']);
  const sabor = getField(rec, ['Sabor', 'Flavor', 'flavor']);
  const contenido = getField(rec, ['Contenido Neto', 'ContenidoNeto', 'contenido_neto', 'Net Content', 'net_content']);

  if (!nombre) continue; // evitamos strings vacíos

  let label = nombre;
  if (sabor) label += ` & ${sabor}`;
  if (contenido) label += ` & ${contenido}`;

  product_options.push(label);
}

// 5) Validación: que no salga vacío
if (product_options.length === 0) {
  throw new Error(
    `No se pudo construir ningún nombre de producto. Revisá que existan campos como "Nombre", "Sabor" y "Contenido Neto" en la salida de "${SOURCE_NODE}" (o en el input directo).`
  );
}

// 6) Devolvemos 1 item con el array (ideal para pasárselo a un AI Agent)
return [
  {
    json: {
      product_options,
      product_options_text: product_options.join('\n'), // útil si preferís meterlo como texto al agente
      count: product_options.length,
    },
  },
];

// n8n Code Node (JavaScript)

// Trae TODOS los items que salieron del nodo "Code in JavaScript3"
const items = $('ObtenerProds Sin sabor').all();

// Armamos el array final de productos (solo strings)
const productos = items
  .map(i => i.json?.producto)
  .filter(p => typeof p === 'string' && p.trim() !== '')
  .map(p => p.trim());

// (opcional) también podés recuperar baseName si lo necesitás
const productos_detalle = items
  .map(i => ({
    producto: (i.json?.producto ?? '').toString().trim(),
    baseName: (i.json?.baseName ?? '').toString().trim(),
    index: i.json?.index ?? null
  }))
  .filter(x => x.producto);

return [
  {
    json: {
      productos,              // <-- array simple ["...", "..."]
      productos_detalle,      // <-- array con info extra
      total: productos.length
    }
  }
];

const input = $input.first().json;

// array de strings: ["Stark ISO-X ... & Vainilla & ...", ...]
const arr = Array.isArray(input.productos) ? input.productos : [];

function escAirtableString(s) {
  // Airtable usa comillas simples, y las comillas simples internas se escapan duplicándolas
  return String(s ?? '').trim().replace(/'/g, "''");
}

function lowerKey(nombre, sabor) {
  return `${String(nombre ?? '').trim().toLowerCase()}|${String(sabor ?? '').trim().toLowerCase()}`;
}

// 1) Parse por "&"
const parsed = arr.map((line, idx) => {
  const parts = String(line ?? '')
    .split('&')
    .map(p => p.trim())
    .filter(Boolean);

  const nombre = parts[0] ?? null;
  const sabor = parts[1] ?? 'Sin sabor';
  const contenido = parts[2] ?? null;

  return {
    idx,
    raw: line,
    nombre,
    sabor,
    contenido,
    key: lowerKey(nombre, sabor),
  };
}).filter(p => p.nombre); // descarta vacíos

// 2) Construir OR( AND(nombre+sabor), AND(...), ... )
const conditions = parsed.map(p => {
  const n = escAirtableString(p.nombre);
  const s = escAirtableString(p.sabor);
  return `AND(LOWER({Nombre})=LOWER('${n}'), LOWER({Sabor})=LOWER('${s}'))`;
});

// Si querés asegurar Activo:
const airtable_formula =
  conditions.length === 0
    ? `FALSE()`
    : `AND({Estado}='Activo', OR(${conditions.join(',')}))`;

return [{
  json: {
    ...input,
    parsed_productos: parsed,
    airtable_formula,
  }
}];

const items = $input.all();

function getFields(j) {
  return (j && j.fields && typeof j.fields === 'object') ? j.fields : (j || {});
}

function clean(v) {
  if (v === undefined || v === null) return null;
  if (typeof v === 'string') {
    const s = v.trim();
    return s.length ? s : null;
  }
  return v;
}

const FIELD_MAP = {
  nombre:        "Nombre",
  categoria:     "Categoría",
  precio:        "Precio",
  sabor:         "Sabor",
  contenido_neto:"Contenido Neto",
  casos_de_uso:  "Casos de Uso",
  como_ingerir:  "Como Ingerir",
};

const productos = items.map((it, idx) => {
  const f = getFields(it.json);
  return {
    producto_n:     idx + 1,
    nombre:         clean(f[FIELD_MAP.nombre]),
    categoria:      clean(f[FIELD_MAP.categoria]),
    precio:         clean(f[FIELD_MAP.precio]),
    sabor:          clean(f[FIELD_MAP.sabor]),
    contenido_neto: clean(f[FIELD_MAP.contenido_neto]),
    casos_de_uso:   clean(f[FIELD_MAP.casos_de_uso]),
    como_ingerir:   clean(f[FIELD_MAP.como_ingerir]),
  };
});

const productos_json = { productos };

const productos_texto = productos.map(p => [
  `[[PRODUCTO_${p.producto_n}]]`,
  `Nombre: ${p.nombre ?? "N/D"}`,
  `Categoría: ${p.categoria ?? "N/D"}`,
  `Precio: ${p.precio ?? "N/D"}`,
  `Sabor: ${p.sabor ?? "N/D"}`,
  `Contenido Neto: ${p.contenido_neto ?? "N/D"}`,
  ``,
  `Casos de Uso:`,
  `${p.casos_de_uso ?? "N/D"}`,
  ``,
  `Como Ingerir:`,
  `${p.como_ingerir ?? "N/D"}`,
  `[[/PRODUCTO_${p.producto_n}]]`,
].join('\n')).join('\n\n-----\n\n');

return [{
  json: {
    productos_json,
    productos_json_string: JSON.stringify(productos_json),
    productos_texto,
  }
}];

// n8n Code node (JavaScript)

// Entrada: puede venir en $json.productos, $json.producto, $json.text, etc.
// Ajustá el fallback según tu flujo.
const raw =
  $json.productos ??
  $json.producto ??
  $json.entrada ??
  $json.text ??
  '';

const s = String(raw).trim();

// Separa por "&" y limpia espacios alrededor
const parts = s
  .split('&')
  .map(p => p.trim())
  .filter(Boolean);

// Mapea a campos esperados
const nombre = parts[0] ?? null;
const sabor = parts[1] ?? 'Sin sabor';
const contenido_neto = parts[2] ?? null;

return [
  {
    json: {
      entrada_raw: s,
      nombre,
      sabor,
      contenido_neto,
      parts,
    },
  },
];
