// n8n Code Node (JavaScript)

// 1) Tomamos el output del AI Agent (puede venir como string, objeto, o array como en tu ejemplo)
const raw = $('AI Agent').first().json.output;

// Helpers de parse / extracción
const safeJsonParse = (s, ctx = 'payload') => {
  try {
    return JSON.parse(s);
  } catch (e) {
    throw new Error(`No se pudo parsear JSON en ${ctx}: ${e.message}`);
  }
};

/**
 * Extrae el "data" final con esta lógica:
 * - Si raw es array: toma el primer elemento
 *   - si ese elemento tiene .output => usa eso
 * - Si raw es objeto y tiene .output => usa eso
 * - Si lo que queda es string => JSON.parse
 * - Si lo que queda es objeto => se usa tal cual
 */
const extractData = (rawValue) => {
  if (rawValue == null) {
    throw new Error(`$('AI Agent').first().json.output vino null/undefined`);
  }

  let payload = rawValue;

  // Caso nuevo: output = [ { output: "{...json...}" } ]
  if (Array.isArray(payload)) {
    if (payload.length === 0) {
      throw new Error(`$('AI Agent').first().json.output vino como array vacío`);
    }
    const first = payload[0];

    if (first == null) {
      throw new Error(`$('AI Agent').first().json.output[0] vino null/undefined`);
    }

    // Si es { output: "..." } o { output: {...} }
    if (typeof first === 'object' && first !== null && 'output' in first) {
      payload = first.output;
    } else {
      payload = first;
    }
  } else if (typeof payload === 'object' && payload !== null && 'output' in payload) {
    // Caso: { output: "..." } directo
    payload = payload.output;
  }

  // Ahora payload debería ser string JSON o un objeto ya parseado
  if (typeof payload === 'string') {
    return safeJsonParse(payload, "$('AI Agent').first().json.output (string)");
  }

  if (typeof payload === 'object' && payload !== null) {
    return payload;
  }

  throw new Error(
    `Tipo de payload no soportado: ${typeof payload}. Valor: ${String(payload)}`
  );
};

// 2) Parseo robusto
const data = extractData(raw);

// 3) Elegimos lista de productos
//    Mantiene el comportamiento anterior con posibles_productos,
//    pero si viene null (como tu ejemplo) usa productos_verificados.
const posibles = Array.isArray(data?.posibles_productos) ? data.posibles_productos : [];
const verificados = Array.isArray(data?.productos_verificados) ? data.productos_verificados : [];

// Fuente principal: posibles_productos si es array con contenido; si no, productos_verificados
const productosFuente = posibles.length ? posibles : verificados;

// Helpers de negocio (igual que antes)
const normalize = (s) => String(s ?? '').trim().toLowerCase();

const getBaseName = (s) => {
  const str = String(s ?? '').trim();
  if (!str) return '';
  const idx = str.indexOf('&');
  return (idx === -1 ? str : str.slice(0, idx)).trim();
};

const isSinSabor = (s) => normalize(s).includes('sin sabor');

// 4) Agrupamos por nombre base
const groups = new Map(); // baseNameLower -> { baseName, candidates: [] }

for (const p of productosFuente) {
  if (p == null) continue;
  const original = String(p).trim();
  if (!original) continue;

  const baseName = getBaseName(original);
  const key = normalize(baseName) || normalize(original);

  if (!groups.has(key)) {
    groups.set(key, { baseName, candidates: [] });
  }
  groups.get(key).candidates.push(original);
}

// 5) Para cada grupo: elegir "sin sabor" si existe, si no la primera
const selected = [];
for (const [, group] of groups) {
  const candidates = group.candidates;

  const sinSaborCandidate = candidates.find(isSinSabor);

  selected.push({
    baseName: group.baseName || getBaseName(sinSaborCandidate ?? candidates[0]) || '',
    producto: sinSaborCandidate ?? candidates[0],
    teniaSinSabor: Boolean(sinSaborCandidate),
    variantes_encontradas: candidates.length,
  });
}

// 6) Output: un item por producto final (igual que antes)
return selected.map((x, i) => ({
  json: {
    index: i + 1,
    baseName: x.baseName,
    producto: x.producto,
    teniaSinSabor: x.teniaSinSabor,
    variantes_encontradas: x.variantes_encontradas,
  },
}));

