let items = [];
try {
  items = $items(SOURCE_NODE);
} catch (e) {
  items = $input.all();
}

// 2) Normalizamos a "records" (array de objetos)
const records = [];

for (const item of items) {
  const j = item?.json;

  if (Array.isArray(j)) {
    records.push(...j);
    continue;
  }

  if (Array.isArray(j?.records)) {
    records.push(...j.records);
    continue;
  }

  if (j?.fields && typeof j.fields === 'object') {
    records.push({ id: j.id, createdTime: j.createdTime, ...j.fields });
  } else if (j && typeof j === 'object') {
    records.push(j);
  }
}

// 3) Helpers
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());

const getField = (rec, keys) => {
  for (const k of keys) {
    if (rec && Object.prototype.hasOwnProperty.call(rec, k)) {
      const val = clean(rec[k]);
      if (val) return val;
    }
  }
  return '';
};

// 4) Formateamos "Nombre & Categoría"
const product_options = [];

for (const rec of records) {
  const nombre = getField(rec, ['Nombre', 'name', 'producto', 'Product', 'Title']);
  const categoria = getField(rec, ['Categoría', 'Categoria', 'category', 'Category']);

  if (!nombre) continue;

  let label = nombre;
  if (categoria) label += ` & ${categoria}`;

  product_options.push(label);
}

// 5) Validación
if (product_options.length === 0) {
  throw new Error(
    `No se pudo construir ningún item. Revisá que existan los campos "Nombre" y/o "Categoría" en la salida de "${SOURCE_NODE}" (o en el input directo).`
  );
}

// 6) Bullets con guión + enter
const product_options_text = `- ${product_options.join('\n- ')}`;

// 7) Output
return [
  {
    json: {
      product_options,
      product_options_text,
      count: product_options.length,
    },
  },
];

const items = $input.all();

function getFields(j) {
  return (j && j.fields && typeof j.fields === 'object') ? j.fields : (j || {});
}

function clean(v) {
  if (v === undefined || v === null) return null;
  if (typeof v === 'string') {
    const s = v.trim();
    return s.length ? s : null;
  }
  return v;
}

const FIELD_MAP = {
  nombre:      "Nombre",
