// n8n Code node (JavaScript)
// Input principal: $('AI Agent2').first().json.output
// Ese output suele venir como STRING con JSON adentro.
// Luego:
// - extrae producto_principal (fallback: productos_verificados[0])
// - split por "&"
// - mapea: nombre, categoria (y sabor como alias), contenido_neto

const agentRaw =
  $('AI Agent2').first()?.json?.output ??
  $json.output ??
  $json.text ??
  $json.entrada ??
  '';

const rawStr = (typeof agentRaw === 'string') ? agentRaw : JSON.stringify(agentRaw);
let cleaned = String(rawStr).trim();

// Limpia posibles fences ```json ... ```
cleaned = cleaned
  .replace(/^```(?:json)?/i, '')
  .replace(/```$/i, '')
  .trim();

// Intenta parsear JSON
let parsed = null;

try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback: busca el primer "{" y el último "}" y parsea ese fragmento
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    try {
      parsed = JSON.parse(cleaned.slice(start, end + 1));
    } catch (e2) {
      parsed = null;
    }
  }
}

// Si no pudimos parsear, tratamos el cleaned como si fuera directamente el producto
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    status: null,
    productos_verificados: null,
    posibles_productos: null,
    producto_principal: cleaned,
  };
}

// Elegimos el string del producto a partir del JSON del agente
const productStr =
  (typeof parsed.producto_principal === 'string' && parsed.producto_principal.trim())
    ? parsed.producto_principal.trim()
    : (Array.isArray(parsed.productos_verificados) && parsed.productos_verificados.length)
      ? String(parsed.productos_verificados[0]).trim()
      : '';

const s = String(productStr).trim();

// Split por "&"
const parts = s
  .split('&')
  .map(p => p.trim())
  .filter(Boolean);

// Mapeo de partes (mismo concepto que tu code)
const nombre = parts[0] ?? null;
const categoria = parts[1] ?? null;     // <- recomendado para tu caso "Nombre & Categoría"
const sabor = parts[1] ?? 'Sin sabor';  // <- alias por compatibilidad con tu estructura vieja
const contenido_neto = parts[2] ?? null;

return [
  {
    json: {
      agent_output_raw: cleaned,     // string original (limpio)
      agent_output_parsed: parsed,   // objeto parseado
      status: parsed.status ?? null,
      productos_verificados: parsed.productos_verificados ?? null,
      posibles_productos: parsed.posibles_productos ?? null,
      producto_principal: parsed.producto_principal ?? null,

      entrada_raw: s,               // producto final usado para split
      parts,
      nombre,
      categoria,
      sabor,
      contenido_neto,
    },
  },
];

